CREATE TABLE `spell_threat` (
    `Entry` int unsigned NOT NULL,
    `Threat` int NOT NULL,
    `Multiplier` float NOT NULL,
    `ApBonus` float NOT NULL,
    `InverseEffectMask` tinyint unsigned NOT NULL,
    `BuildMin` int unsigned NOT NULL,
    `BuildMax` int unsigned NOT NULL,
    CONSTRAINT `PK_spell_threat` PRIMARY KEY (`Entry`)
) CHARACTER SET=utf8mb4;

CREATE TABLE `taxi_nodes` (
    `id` int unsigned NOT NULL,
    `map_id` int unsigned NOT NULL,
    `x` float NOT NULL,
    `y` float NOT NULL,
    `z` float NOT NULL,
    `name` longtext CHARACTER SET utf8mb4 NOT NULL,
    `mount_horde` int unsigned NOT NULL,
    `mount_alliance` int unsigned NOT NULL,
    CONSTRAINT `PK_taxi_nodes` PRIMARY KEY (`id`)
) CHARACTER SET=utf8mb4;

CREATE TABLE `taxi_path` (
    `id` int unsigned NOT NULL,
    `from_node` int unsigned NOT NULL,
    `to_node` int unsigned NOT NULL,
    `price` int unsigned NOT NULL,
    CONSTRAINT `PK_taxi_path` PRIMARY KEY (`id`)
) CHARACTER SET=utf8mb4;

CREATE TABLE `totem_spell` (
    `CreatureEntry` int unsigned NOT NULL,
    `SpellId` int unsigned NOT NULL,
    CONSTRAINT `PK_totem_spell` PRIMARY KEY (`CreatureEntry`)
